  'blog.surv.td1':          { en: '<strong>Cap_able</strong> (Italy)', es: '<strong>Cap_able</strong> (Italia)' },
  'blog.surv.td2':          { en: 'Knitted sweaters, pants, dresses', es: 'Suéteres, pantalones, vestidos de punto' },
  'blog.surv.td3':          { en: 'Adversarial patterns make wearer appear as an animal (dog, zebra) instead of a person', es: 'Patrones adversariales hacen que el usuario parezca un animal (perro, cebra) en lugar de una persona' },
  'blog.surv.td4':          { en: '~$310+', es: '~310 USD+' },
  'blog.surv.td5':          { en: 'YOLO real-time detection<sup><a href="#fn7" id="fnref7" class="fn-ref">[7]</a></sup><sup><a href="#fn8" id="fnref8" class="fn-ref">[8]</a></sup>', es: 'Detección en tiempo real YOLO<sup><a href="#fn7" id="fnref7" class="fn-ref">[7]</a></sup><sup><a href="#fn8" id="fnref8" class="fn-ref">[8]</a></sup>' },
