  'blog.prep.h3_commplan':   { en: 'Communication Plan', es: 'Plan de comunicación' },
  'blog.prep.h3_finance':    { en: 'Financial Resilience Strategy', es: 'Estrategia de resiliencia financiera' },
  'blog.prep.h3_homekit':    { en: 'Home Emergency Supply Kit (2-Week Minimum)', es: 'Kit de suministros de emergencia (mínimo 2 semanas)' },
  'blog.prep.h3_gobag':      { en: 'Go-Bag (72-Hour Kit)', es: 'Bolsa de emergencia (kit 72 horas)' },
