  // Conclusion
  'blog.prep.conclusion_p1': { en: 'The most critical principle is <strong>"two is one, one is none"</strong> - always have backups for essential systems. Start with the basics (water, food, cash, communication) and expand gradually. Focus on skills and community connections as much as physical supplies.', es: '' },
  'blog.prep.conclusion_bq': { en: '<strong>Remember</strong>: The goal is resilience, not paranoia. Regular, incremental preparation reduces anxiety and increases your ability to weather any crisis. The federal government is actively training responders for these scenarios, indicating they are recognized risks worth preparing for.<sup><a href="#fn21" id="fnref21" class="fn-ref">[21]</a></sup><sup><a href="#fn17" id="fnref17b" class="fn-ref">[17]</a></sup><sup><a href="#fn18" id="fnref18e" class="fn-ref">[18]</a></sup>', es: '' },

  'blog.merrillcard.title':    { en: 'Privacy Protection: Actionable Steps for 2026',
                               es: 'Protección de privacidad: pasos concretos para 2026' },
  'blog.merrillcard.desc':     { en: 'Based on Nicholas Merrill\'s privacy-first philosophy: concrete steps for phones (Phreeli, CalyxOS), WiFi, home devices, and proximity-based protection.',
                               es: 'Basado en la filosofía de privacidad primero de Nicholas Merrill: pasos concretos para teléfonos (Phreeli, CalyxOS), WiFi, dispositivos del hogar y protección por proximidad.' },
