  // Part 4: Finding a Detained Loved One
  'res.p4.intro':         { en: 'If someone you know has been arrested by ICE, follow these steps (from ', es: 'Si alguien que conoces ha sido arrestado por ICE, sigue estos pasos (de ' },
  'res.p4.nilc_guide':    { en: 'NILC guide', es: 'guía de NILC' },
  'res.p4.step1':         { en: 'Step 1: ICE Online Detainee Locator System', es: 'Paso 1: Sistema de Localización de Detenidos en Línea de ICE' },
  'res.p4.step1.1':       { en: 'Search by <strong>A-Number</strong> (alien registration number) + country of birth, OR by name + country of birth', es: 'Busca por <strong>Número A</strong> (número de registro de extranjería) + país de nacimiento, O por nombre + país de nacimiento' },
  'res.p4.step1.2':       { en: 'It can take <strong>24&ndash;48 hours</strong> for a name to appear', es: 'Puede tardar <strong>24&ndash;48 horas</strong> en aparecer un nombre' },
  'res.p4.step1.3':       { en: '<strong>Exceptions</strong>: Children under 18, T/U visa cases, and some transfers may not appear', es: '<strong>Excepciones</strong>: Menores de 18 años, casos de visa T/U y algunos traslados pueden no aparecer' },
  'res.p4.step2':         { en: 'Step 2: Contact the ICE Field Office (ERO)', es: 'Paso 2: Contactar la Oficina de Campo de ICE (ERO)' },
  'res.p4.step2.1':       { en: 'Call or email your local <strong>ICE Enforcement and Removal Operations</strong> office', es: 'Llama o escribe al correo de tu oficina local de <strong>Operaciones de Cumplimiento y Remoción de ICE</strong>' },
  'res.p4.step2.2':       { en: 'Only provide necessary identifying information (A-number, name, country of birth)', es: 'Solo proporciona la información de identificación necesaria (número A, nombre, país de nacimiento)' },
  'res.p4.step2.3':       { en: 'Ask for the <strong>Deportation Officer</strong> assigned to the case', es: 'Pide el <strong>Oficial de Deportación</strong> asignado al caso' },
  'res.p4.step3':         { en: 'Step 3: Check the Bureau of Prisons (BOP)', es: 'Paso 3: Consultar la Oficina de Prisiones (BOP)' },
  'res.p4.step3.1':       { en: 'Since 2025, ICE has used BOP facilities to hold immigration detainees', es: 'Desde 2025, ICE ha usado instalaciones de BOP para detener a inmigrantes' },
  'res.p4.step4':         { en: 'Step 4: Contact Consulates', es: 'Paso 4: Contactar Consulados' },
  'res.p4.step4.1':       { en: 'All immigrants in ICE custody have the right to contact their country\'s consulate', es: 'Todos los inmigrantes bajo custodia de ICE tienen derecho a contactar el consulado de su país' },
  'res.p4.step4.2':       { en: '<strong>Do NOT contact the consulate</strong> if the person is seeking asylum or fears their government', es: '<strong>NO contactes al consulado</strong> si la persona busca asilo o teme a su gobierno' },
  'res.p4.step5':         { en: 'Step 5: Cross-Reference Facility Lists', es: 'Paso 5: Cruzar Listas de Instalaciones' },
  'res.p4.step5.1':       { en: 'ICE Detention Facilities list', es: 'Lista de instalaciones de detención de ICE' },
  'res.p4.step5.1_suffix': { en: '(Excel spreadsheet at bottom)', es: '(hoja Excel al final)' },
  'res.p4.step5.2':       { en: '<strong>Freedom for Immigrants</strong>: Searchable list of ICE detention centers with contact info', es: '<strong>Freedom for Immigrants</strong>: Lista buscable de centros de detención de ICE con información de contacto' },
  'res.p4.when_find':     { en: 'What to Do When You Find Them', es: 'Qué Hacer Cuando Los Encuentres' },
  'res.p4.when_find.1':   { en: 'Get proof of community ties (school records, work verification, volunteer records) for bond hearings', es: 'Obtén prueba de lazos comunitarios (registros escolares, verificación laboral, voluntariado) para audiencias de fianza' },
  'res.p4.when_find.2':   { en: 'Ensure they know: <strong>do not sign anything</strong> labeled "waiver," "stipulated removal order," or "voluntary departure agreement" without a lawyer', es: 'Asegúrate de que sepan: <strong>no firmen nada</strong> con "renuncia," "orden de deportación acordada" o "acuerdo de salida voluntaria" sin un abogado' },
  'res.p4.when_find.3':   { en: 'If they fear return to home country, they should say so <strong>loudly and clearly</strong> to every officer', es: 'Si temen regresar a su país, deben decirlo <strong>fuerte y claro</strong> a cada oficial' },

  // Part 5: Family Emergency Preparedness
  'res.p5.templates':     { en: 'Preparedness Plan Templates', es: 'Plantillas de Plan de Preparación' },
  'res.p5.key_steps':     { en: 'Key Steps for Your Family Plan', es: 'Pasos Clave para Tu Plan Familiar' },
  'res.p5.step.1':       { en: '<strong>Designate a trusted guardian</strong> for your children in case of detention/deportation', es: '<strong>Designa un tutor de confianza</strong> para tus hijos en caso de detención/deportación' },
  'res.p5.step.2':       { en: '<strong>Gather and copy</strong> important documents: birth certificates, passports, immigration papers, medical records, school records', es: '<strong>Reúne y copia</strong> documentos importantes: actas de nacimiento, pasaportes, papeles de inmigración, expedientes médicos, expedientes escolares' },
  'res.p5.step.3':       { en: '<strong>Create a folder labeled "Privileged &amp; Confidential"</strong> &mdash; store with a trusted person', es: '<strong>Crea una carpeta etiquetada "Privilegiado y Confidencial"</strong> &mdash; guárdala con una persona de confianza' },
  'res.p5.step.4':       { en: '<strong>Memorize key phone numbers</strong> &mdash; attorney, emergency contact, consulate', es: '<strong>Memoriza números clave</strong> &mdash; abogado, contacto de emergencia, consulado' },
  'res.p5.step.5':       { en: '<strong>Download the Notifica app</strong> &mdash; sends automatic alerts to emergency contacts if you are detained', es: '<strong>Descarga la app Notifica</strong> &mdash; envía alertas automáticas a contactos de emergencia si te detienen' },
  'res.p5.step.6':       { en: '<strong>Carry your work permit or proof of legal status</strong> (if applicable) &mdash; but <strong>never carry a foreign passport</strong> or foreign ID (it can speed up deportation)', es: '<strong>Lleva tu permiso de trabajo o prueba de estatus legal</strong> (si aplica) &mdash; pero <strong>nunca lleves pasaporte extranjero</strong> ni ID extranjero (puede acelerar la deportación)' },
  'res.p5.step.7':       { en: '<strong>Do NOT sign any documents</strong> without talking to a lawyer', es: '<strong>NO firmes ningún documento</strong> sin hablar con un abogado' },
  'res.p5.step.8':       { en: '<strong>Sync photos/videos to the cloud</strong> &mdash; in case you record an ICE encounter, others can access the footage', es: '<strong>Sincroniza fotos/videos a la nube</strong> &mdash; si grabas un encuentro con ICE, otros pueden acceder al material' },

  // Part 5 Preparedness Plan Templates table
