  'res.p6.types.1':      { en: '<strong>Grocery shopping &amp; supply delivery</strong> for families afraid to leave their homes', es: '<strong>Compras y entrega de suministros</strong> para familias que temen salir de casa' },
  'res.p6.types.2':      { en: '<strong>School drop-off/pick-up watches</strong> &mdash; monitor for ICE activity near schools', es: '<strong>Vigilancias en entradas/salidas de escuelas</strong> &mdash; monitorear actividad de ICE cerca de escuelas' },
