  // Key Reminders section
  'res.reminders.title':   { en: 'Key Reminders', es: 'Recordatorios Clave' },
  'res.reminders.1':      { en: '<strong>You have constitutional rights regardless of immigration status</strong> &mdash; including the right to remain silent, the right to an attorney, and the right to refuse entry without a judicial warrant', es: '<strong>Tienes derechos constitucionales sin importar tu estatus migratorio</strong> &mdash; incluido el derecho a guardar silencio, a un abogado y a negar la entrada sin una orden judicial' },
  'res.reminders.2':      { en: '<strong>Do not open the door</strong> for ICE unless they show a <strong>judicial warrant signed by a judge</strong> (not an administrative ICE warrant)', es: '<strong>No abras la puerta</strong> a ICE a menos que muestren una <strong>orden judicial firmada por un juez</strong> (no una orden administrativa de ICE)' },
  'res.reminders.3':      { en: '<strong>Do not sign anything</strong> without speaking to a lawyer', es: '<strong>No firmes nada</strong> sin hablar con un abogado' },
  'res.reminders.4':      { en: '<strong>Do not carry a foreign passport</strong> &mdash; it can accelerate deportation', es: '<strong>No lleves pasaporte extranjero</strong> &mdash; puede acelerar la deportación' },
  'res.reminders.5':      { en: '<strong>Preparation is power</strong> &mdash; complete a family preparedness plan and store it with a trusted person today', es: '<strong>La preparación es poder</strong> &mdash; completa un plan de preparación familiar y guárdalo con una persona de confianza hoy' },
  'res.reminders.6':      { en: '<strong>Save your local rapid response hotline</strong> in your phone now, before an emergency', es: '<strong>Guarda la línea de respuesta rápida local</strong> en tu teléfono ahora, antes de una emergencia' },
  'res.reminders.footer': { en: 'This page was compiled on February 11, 2026 from live web sources. Check individual organization websites for the most current information and resources.', es: 'Esta página se compiló el 11 de febrero de 2026 a partir de fuentes web en vivo. Consulta los sitios de cada organización para la información y recursos más actuales.' },
  'res.last_updated':    { en: 'Last Updated: February 11, 2026', es: 'Última actualización: 11 de febrero de 2026' },

