  'blog.merrill.zero_trust_intro': { en: 'Based on Merrill\'s "privacy by design" philosophy, implement zero-trust principles:', es: 'Basado en la filosofía "privacidad por diseño" de Merrill, implementa principios de confianza cero:' },
  'blog.merrill.adv_1_h3':   { en: '1. Assume Breach Mentality', es: '1. Mentalidad de asumir brecha' },
  'blog.merrill.breach_1':    { en: 'Compartmentalize data: Use different devices for different purposes (work, personal, sensitive)', es: 'Compartimenta datos: usa dispositivos distintos para distintos fines (trabajo, personal, sensible)' },
  'blog.merrill.breach_2':    { en: 'Encrypt everything: Full disk encryption on all devices, use VeraCrypt for external drives', es: 'Cifra todo: cifrado de disco completo en todos los dispositivos, usa VeraCrypt para discos externos' },
  'blog.merrill.breach_3':    { en: 'Regular factory resets: Wipe and reinstall phone OS monthly to clear potential malware', es: 'Restablecimientos de fábrica regulares: borra y reinstala el OS del teléfono mensualmente para limpiar posible malware' },
