  'blog.merrill.meta_1':      { en: 'Use Matrix/Element instead of SMS: Decentralized, encrypted messaging with minimal metadata', es: 'Usa Matrix/Element en lugar de SMS: mensajería descentralizada y cifrada con metadatos mínimos' },
  'blog.merrill.meta_2':      { en: 'Disable read receipts and typing indicators: Reduces behavioral metadata', es: 'Desactiva confirmaciones de lectura e indicadores de escritura: reduce metadatos de comportamiento' },
