  'blog.merrill.phys_4':      { en: 'Tamper-evident seals: Place stickers on device screws to detect physical access', es: 'Sellos antimanipulación: coloca pegatinas en los tornillos del dispositivo para detectar acceso físico' },
  'blog.merrill.checklist_h2': { en: 'Implementation Checklist for January 2026', es: 'Lista de implementación para enero de 2026' },
  'blog.merrill.immediate':   { en: 'Immediate Actions (This Week)', es: 'Acciones inmediatas (esta semana)' },
  'blog.merrill.chk_1':       { en: 'Sign up for Phreeli at https://www.phreeli.com/privacy', es: 'Regístrate en Phreeli en https://www.phreeli.com/privacy' },
  'blog.merrill.chk_2':       { en: 'Audit all app permissions on your phone', es: 'Audita todos los permisos de apps en tu teléfono' },
  'blog.merrill.chk_3':       { en: 'Enable MAC randomization for WiFi networks', es: 'Activa la aleatorización MAC para redes WiFi' },
  'blog.merrill.chk_4':       { en: 'Change router admin password and disable remote management', es: 'Cambia la contraseña de administrador del router y desactiva la administración remota' },
  'blog.merrill.chk_5':       { en: 'Install Signal and set as default SMS app', es: 'Instala Signal y configúralo como app de SMS por defecto' },
