  'blog.merrill.chk_7':       { en: 'Set up Pi-hole or AdGuard Home on home network', es: 'Configura Pi-hole o AdGuard Home en la red doméstica' },
  'blog.merrill.chk_8':       { en: 'Create separate VLANs for IoT devices', es: 'Crea VLANs separadas para dispositivos IoT' },
  'blog.merrill.chk_9':       { en: 'Purchase Faraday bag for sensitive situations', es: 'Compra una bolsa Faraday para situaciones sensibles' },
