  'blog.merrill.chk_14':      { en: 'Conduct quarterly privacy audits of all services and devices', es: 'Realiza auditorías de privacidad trimestrales de todos los servicios y dispositivos' },
  'blog.merrill.chk_15':      { en: 'Attend FOSDEM 2026 (Jan 31) to learn about latest privacy developments', es: 'Asiste a FOSDEM 2026 (31 ene) para conocer los últimos avances en privacidad' },
